<?php
declare(strict_types=1);require_once __DIR__.'/config/finance_step16.php';$error=null;$from=trim((string)($_GET['from']??date('Y-01-01')));$to=trim((string)($_GET['to']??date('Y-m-d')));$rows=[];$tot=['in'=>0.0,'out'=>0.0,'net'=>0.0];
try{$pdo=business_db();finance_step16_ensure($pdo);finance_step16_sync_all($pdo);$ctx=finance_step16_context($pdo);$orgId=(int)$ctx['organization_id'];$from=finance_step16_date($from,'from date');$to=finance_step16_date($to,'to date');$stmt=$pdo->prepare("SELECT DATE_FORMAT(j.journal_date,'%Y-%m') month_key,j.journal_type,j.source_type,SUM(CASE WHEN l.debit_amount>0 THEN l.debit_amount ELSE 0 END) inflow,SUM(CASE WHEN l.credit_amount>0 THEN l.credit_amount ELSE 0 END) outflow FROM finance_journal_lines l JOIN finance_journals j ON j.id=l.journal_id AND j.organization_id=l.organization_id WHERE l.organization_id=? AND l.cash_account_id IS NOT NULL AND j.journal_date BETWEEN ? AND ? GROUP BY DATE_FORMAT(j.journal_date,'%Y-%m'),j.journal_type,j.source_type ORDER BY month_key DESC,j.journal_type,j.source_type");$stmt->execute([$orgId,$from,$to]);$rows=$stmt->fetchAll();foreach($rows as &$r){$r['net']=round((float)$r['inflow']-(float)$r['outflow'],2);$tot['in']+=(float)$r['inflow'];$tot['out']+=(float)$r['outflow'];}unset($r);$tot['net']=round($tot['in']-$tot['out'],2);}catch(Throwable $e){$error=$e->getMessage();}
function cf_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function cf_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Cash Flow - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/step10.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="finance_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 16 • Direct Cash Flow</small></span></a><div class="os-top-actions"><a class="os-btn" href="finance_cashbook.php">Cashbook</a><a class="os-btn" href="finance_profit_loss.php">P&amp;L</a><a class="os-btn primary" href="finance_center.php">Finance Center</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Statements</div><nav class="os-nav"><a href="finance_center.php"><i class="dot"></i>Finance Center</a><a href="finance_profit_loss.php"><i class="dot"></i>Profit & Loss</a><a class="active" href="finance_cash_flow.php"><i class="dot"></i>Cash Flow</a><a href="finance_monthly.php"><i class="dot"></i>Monthly Summary</a></nav></aside><main class="os-main"><section class="os-hero s10-hero"><div class="os-kicker">STEP 16F • DIRECT CASH FLOW</div><h1>See money that actually moved through Cash, Bank, UPI, Card and clearing accounts.</h1><p>This is a direct cash-movement view. Accrual-only entries such as unpaid sales invoices or supplier bills are excluded until a liquid account is affected.</p></section><section class="os-card" style="margin-top:14px"><form method="get" class="pp-form"><label>From<input type="date" name="from" value="<?= cf_h($from) ?>"></label><label>To<input type="date" name="to" value="<?= cf_h($to) ?>"></label><button>Generate</button></form></section><?php if($error):?><div class="pp-alert bad"><strong>Cash-flow diagnostic:</strong> <?= cf_h($error) ?></div><?php else:?><section class="s10-kpis"><div class="s10-kpi"><small>Total Inflow</small><strong><?= cf_m($tot['in']) ?></strong></div><div class="s10-kpi"><small>Total Outflow</small><strong><?= cf_m($tot['out']) ?></strong></div><div class="s10-kpi"><small>Net Cash Movement</small><strong><?= cf_m($tot['net']) ?></strong></div><div class="s10-kpi"><small>Period</small><strong><?= cf_h($from) ?></strong><span>to <?= cf_h($to) ?></span></div></section><section class="os-card" style="margin-top:14px"><h2>Monthly Cash Movement</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Month</th><th>Journal Type</th><th>Source</th><th>Inflow</th><th>Outflow</th><th>Net</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?= cf_h($r['month_key']) ?></b></td><td><?= cf_h($r['journal_type']) ?></td><td><?= cf_h($r['source_type']?:'manual') ?></td><td><?= cf_m($r['inflow']) ?></td><td><?= cf_m($r['outflow']) ?></td><td><b><?= cf_m($r['net']) ?></b></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">No liquid-account movement in this period.</td></tr><?php endif;?></tbody></table></div></section><div class="os-footer-note"><strong>Cash-flow rule:</strong> transfers between your own liquid accounts create equal inflow/outflow and therefore zero net business cash movement.</div><?php endif;?></main></div></body></html>